function solve(grid) {
  const g = grid.map((row) => row.slice());
  const m = g.length;
  if (!m) return 0;
  const n = g[0].length;
  let count = 0;
  const flood = (r, c) => {
    if (r < 0 || r >= m || c < 0 || c >= n || g[r][c] !== '1') return;
    g[r][c] = '0';
    flood(r + 1, c);
    flood(r - 1, c);
    flood(r, c + 1);
    flood(r, c - 1);
  };
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      if (g[r][c] === '1') {
        count++;
        flood(r, c);
      }
    }
  }
  return count;
}
